(function(){
const {useState,useEffect,useMemo}=React,html=htm.bind(React.createElement);
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Math.round(Number(n)||0));
const shortMoney=n=>{n=Number(n)||0;return n>=100000?'₹'+(n/100000).toFixed(1)+'L':n>=1000?'₹'+(n/1000).toFixed(n>=10000?0:1)+'k':money(n)};
const today=()=>new Date().toISOString().slice(0,10), uid=()=>Math.random().toString(36).slice(2,10);
const categories=['Food','Transport','Rent & Housing','Education','Bills','Health','Shopping','Entertainment','Subscriptions','Savings','Other'];
const incomeCats=['Part-time work','Freelance','Allowance','Refund','Other income'];
const navItems=[['Overview','layout-dashboard'],['Transactions','arrow-left-right'],['Decision Lab','flask-conical'],['Budget Planner','sliders-horizontal'],['Bills & Subscriptions','calendar-clock'],['Savings Goals','target'],['Financial Health','heart-pulse'],['Money Coach','messages-square'],['Settings','settings']];
const iconMap={'Food':'utensils','Transport':'bus','Rent & Housing':'house','Education':'graduation-cap','Bills':'receipt','Health':'heart-pulse','Shopping':'shopping-bag','Entertainment':'clapperboard','Subscriptions':'repeat','Savings':'piggy-bank','Other':'circle-dot','Part-time work':'briefcase-business','Freelance':'laptop','Allowance':'wallet','Refund':'rotate-ccw','Other income':'plus-circle'};
const defaults=()=>({budget:10000,days:30,startDate:today(),transactions:[],bills:[],goals:[{id:'g1',name:'Emergency buffer',target:3000,saved:0,due:today()}],lang:'English',demo:false});
function load(){try{const d=JSON.parse(localStorage.getItem('barely-state-v1'));if(d&&typeof d==='object'&&Number.isFinite(d.budget)&&Array.isArray(d.transactions))return {...defaults(),...d}}catch(e){}return defaults()}
const txt={English:{Overview:'Overview',Transactions:'Transactions','Decision Lab':'Decision Lab','Budget Planner':'Budget Planner','Bills & Subscriptions':'Bills & Subscriptions','Savings Goals':'Savings Goals','Financial Health':'Financial Health','Money Coach':'Money Coach',Settings:'Settings',remaining:'Available balance',safe:'Safe to spend today',days:'days left',projection:'Projected month-end',spending:'Spending trend',categories:'Where it goes',recent:'Recent transactions',advice:'A little money clarity',simulate:'Simulate a decision'},Tamil:{Overview:'கண்ணோட்டம்',Transactions:'பரிவர்த்தனைகள்','Decision Lab':'முடிவு ஆய்வகம்','Budget Planner':'பட்ஜெட் திட்டம்','Bills & Subscriptions':'கட்டணங்கள்','Savings Goals':'சேமிப்பு இலக்குகள்','Financial Health':'நிதி நிலை','Money Coach':'பண ஆலோசகர்',Settings:'அமைப்புகள்',remaining:'கையில் உள்ள தொகை',safe:'இன்று செலவிடலாம்',days:'நாட்கள் மீதம்',projection:'மாத இறுதி கணிப்பு',spending:'செலவு போக்கு',categories:'செலவுகள் எங்கே',recent:'சமீபத்திய பரிவர்த்தனைகள்',advice:'பணத்தைப் புரிந்துகொள்வோம்',simulate:'முடிவைச் சோதிக்கவும்'},Hindi:{Overview:'अवलोकन',Transactions:'लेन-देन','Decision Lab':'निर्णय लैब','Budget Planner':'बजट योजना','Bills & Subscriptions':'बिल और सदस्यताएँ','Savings Goals':'बचत लक्ष्य','Financial Health':'वित्तीय स्वास्थ्य','Money Coach':'मनी कोच',Settings:'सेटिंग्स',remaining:'उपलब्ध राशि',safe:'आज सुरक्षित खर्च',days:'दिन शेष',projection:'महीने के अंत का अनुमान',spending:'खर्च का रुझान',categories:'खर्च कहाँ हुआ',recent:'हाल के लेन-देन',advice:'पैसे की स्पष्टता',simulate:'निर्णय का अनुकरण'},Telugu:{Overview:'అవలోకనం',Transactions:'లావాదేవీలు','Decision Lab':'నిర్ణయ ప్రయోగశాల','Budget Planner':'బడ్జెట్ ప్రణాళిక','Bills & Subscriptions':'బిల్లులు','Savings Goals':'పొదుపు లక్ష్యాలు','Financial Health':'ఆర్థిక ఆరోగ్యం','Money Coach':'మనీ కోచ్',Settings:'సెట్టింగ్‌లు',remaining:'అందుబాటులో ఉన్న మొత్తం',safe:'ఈ రోజు ఖర్చు',days:'రోజులు మిగిలాయి',projection:'నెలాఖరు అంచనా',spending:'ఖర్చు ధోరణి',categories:'ఖర్చులు ఎక్కడ',recent:'ఇటీవలి లావాదేవీలు',advice:'డబ్బుపై స్పష్టత',simulate:'నిర్ణయాన్ని అనుకరించు'},Malayalam:{Overview:'അവലോകനം',Transactions:'ഇടപാടുകൾ','Decision Lab':'തീരുമാന ലാബ്','Budget Planner':'ബജറ്റ് പ്ലാനർ','Bills & Subscriptions':'ബില്ലുകൾ','Savings Goals':'സേവിംഗ്സ് ലക്ഷ്യങ്ങൾ','Financial Health':'സാമ്പത്തിക ആരോഗ്യം','Money Coach':'മണി കോച്ച്',Settings:'ക്രമീകരണങ്ങൾ',remaining:'ലഭ്യമായ തുക',safe:'ഇന്ന് ചെലവാക്കാം',days:'ദിവസങ്ങൾ ബാക്കി',projection:'മാസാവസാന പ്രവചനം',spending:'ചെലവ് പ്രവണത',categories:'ചെലവുകൾ എവിടെ',recent:'സമീപകാല ഇടപാടുകൾ',advice:'പണത്തെക്കുറിച്ചുള്ള വ്യക്തത',simulate:'തീരുമാനം പരീക്ഷിക്കുക'},Bengali:{Overview:'সংক্ষিপ্ত বিবরণ',Transactions:'লেনদেন','Decision Lab':'সিদ্ধান্ত ল্যাব','Budget Planner':'বাজেট পরিকল্পনা','Bills & Subscriptions':'বিল ও সাবস্ক্রিপশন','Savings Goals':'সঞ্চয়ের লক্ষ্য','Financial Health':'আর্থিক স্বাস্থ্য','Money Coach':'মানি কোচ',Settings:'সেটিংস',remaining:'উপলব্ধ ব্যালেন্স',safe:'আজ নিরাপদে খরচ',days:'দিন বাকি',projection:'মাসশেষের পূর্বাভাস',spending:'খরচের প্রবণতা',categories:'খরচ কোথায়',recent:'সাম্প্রতিক লেনদেন',advice:'টাকা নিয়ে স্পষ্টতা',simulate:'সিদ্ধান্ত অনুকরণ'}};
function App(){
const [data,setData]=useState(load),[page,setPage]=useState('Overview'),[modal,setModal]=useState(null),[toast,setToast]=useState(null),[query,setQuery]=useState(''),[filter,setFilter]=useState('All'),[sort,setSort]=useState('new'),[editing,setEditing]=useState(null),[decision,setDecision]=useState({type:'expense',amount:'800',category:'Entertainment',name:'Movie night',date:today(),recurring:false,notes:''}),[quick,setQuick]=useState(''),[parsed,setParsed]=useState(null);
useEffect(()=>{try{localStorage.setItem('barely-state-v1',JSON.stringify(data))}catch(e){}},[data]);
useEffect(()=>{if(toast){const id=setTimeout(()=>setToast(null),2800);return()=>clearTimeout(id)}},[toast]);
const t=txt[data.lang]||txt.English;
const metrics=useMemo(()=>calculate(data),[data]);
function update(p){setData(d=>({...d,...(typeof p==='function'?p(d):p)}))}
function notify(message,error=false){setToast({message,error})}
function icon(name,size){return html`<i data-lucide=${name} style=${size?{width:size,height:size}:null}></i>`}
useEffect(()=>{if(window.lucide)window.lucide.createIcons()},[page,modal,data,toast]);
function calculate(d){
const income=d.transactions.filter(x=>x.type==='income').reduce((s,x)=>s+x.amount,0),spent=d.transactions.filter(x=>x.type==='expense').reduce((s,x)=>s+x.amount,0);
const balance=d.budget+income-spent,unpaid=d.bills.filter(b=>!b.paid),committed=unpaid.reduce((s,b)=>s+b.amount,0),savings=d.goals.reduce((s,g)=>s+g.saved,0),spendable=balance-committed-savings;
const start=new Date(d.startDate+'T00:00:00'),elapsed=Math.max(0,Math.floor((new Date(today()+'T00:00:00')-start)/86400000)),remaining=Math.max(0,d.days-elapsed),elapsedSafe=Math.max(1,Math.min(d.days,elapsed+1));
const plannedDaily=d.budget/Math.max(1,d.days),daily=remaining>0?Math.max(0,spendable/remaining):Math.max(0,spendable);
const upcoming=unpaid.filter(b=>b.due>=today()).reduce((s,b)=>s+b.amount,0);
const dailyActual=spent/elapsedSafe,projected=balance-Math.max(0,dailyActual*remaining)-committed;
const essential=unpaid.filter(b=>b.essential).reduce((s,b)=>s+b.amount,0),risk=balance<0||spendable<0||projected<0?'High risk':spendable<plannedDaily*remaining*.35||dailyActual>plannedDaily*1.2?'Caution':'Healthy';
const goalProgress=d.goals.length?Math.round(d.goals.reduce((s,g)=>s+Math.min(1,g.saved/Math.max(1,g.target)),0)/d.goals.length*100):0;
const pace=Math.max(0,Math.min(100,Math.round((1-(dailyActual/Math.max(1,plannedDaily)))*55+Math.min(1,Math.max(0,spendable)/Math.max(1,d.budget))*30+(balance>=essential?15:0))));
return {income,spent,balance,unpaid,committed,savings,spendable,remaining,daily,plannedDaily,upcoming,projected,essential,risk,goalProgress,score:Math.max(0,Math.min(100,pace)),dailyActual,elapsed};
}
function transact(tx){if(!tx.name||!Number.isFinite(tx.amount)||tx.amount<=0){notify('Enter a description and an amount above ₹0.',true);return}if(tx.type==='expense'&&tx.amount>metrics.balance+10000000){notify('Invalid expense amount.',true);return}update(d=>({...d,transactions:editing?d.transactions.map(x=>x.id===editing.id?{...tx,id:editing.id}:x):[{...tx,id:uid(),createdAt:Date.now()},...d.transactions]}));setModal(null);setEditing(null);notify(editing?'Transaction updated':'Transaction saved')}
function deleteTx(id){if(!confirm('Delete this transaction? Your totals will update.'))return;update(d=>({...d,transactions:d.transactions.filter(x=>x.id!==id)}));notify('Transaction deleted')}
function reset(){if(!confirm('Reset barely. to the original ₹10,000 / 30-day scenario? Your local transaction, bill and goal data will be removed.'))return;setData(defaults());setPage('Overview');setModal(null);notify('Original scenario restored')}
function addModal(kind){setEditing(null);setModal(kind)}
function applyDecision(){const amount=Math.round(Number(decision.amount));if(!Number.isFinite(amount)||amount<=0){notify('Enter a valid amount.',true);return}if(decision.type==='expense'&&amount>metrics.balance){notify('This expense exceeds your available cash. It cannot be applied.',true);return}if(decision.type==='expense'&&decision.recurring&&amount*(metrics.remaining>0?Math.ceil(metrics.remaining/30):0)>metrics.balance){notify('This recurring cost is not sustainable for the remaining period.',true);return}const type=decision.type==='income'?'income':decision.type==='expense'?'expense':'adjustment';if(type==='adjustment'){update(d=>({...d,transactions:[{id:uid(),name:decision.name||'Subscription cancelled',amount:0,type:'adjustment',category:decision.category,date:decision.date,notes:decision.notes},...d.transactions]}));}else transact({name:decision.name||decision.category,amount,type,category:decision.category,date:decision.date||today(),notes:decision.notes||'',recurring:decision.recurring});setModal(null);setPage('Overview')}
function exportCSV(){const rows=[['Date','Description','Type','Category','Amount'],...data.transactions.map(x=>[x.date,x.name,x.type,x.category,x.amount])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='barely-transactions.csv';a.click();URL.revokeObjectURL(a.href);notify('CSV export prepared')}
function quickParse(){const s=quick.trim();const match=s.match(/(?:₹|rs\.?\s*)?([0-9]+(?:,[0-9]{3})*(?:\.[0-9]{1,2})?)/i);if(!s||!match){notify('Add a command with an amount, e.g. “Spent 250 on lunch”.',true);return}const amount=Number(match[1].replace(/,/g,''));const lower=s.toLowerCase();const type=/\b(income|received|earned|got paid|refund)\b/.test(lower)?'income':'expense';let category='Other';for(const c of categories){const words=c.toLowerCase().split(/[^a-z]+/).filter(Boolean);if(words.some(w=>w.length>3&&lower.includes(w))){category=c;break}}if(/lunch|food|snack|dinner|breakfast|coffee/.test(lower))category='Food';if(/bus|auto|cab|fuel|travel/.test(lower))category='Transport';if(/movie|game|netflix|music/.test(lower))category='Entertainment';if(/rent|hostel/.test(lower))category='Rent & Housing';if(type==='income')category=/freelance/.test(lower)?'Freelance':/part.time|salary|work/.test(lower)?'Part-time work':'Other income';const name=s.replace(match[0],'').replace(/spent|income|received|earned|on|for|from/ig,' ').trim().replace(/\s+/g,' ')||category;setParsed({name,amount,type,category,date:today()});}
function commitParsed(){if(parsed){transact({...parsed,notes:'Added with Quick Add'});setParsed(null);setQuick('')}}
function startDecision(){setDecision({type:'expense',amount:'800',category:'Entertainment',name:'Movie night',date:today(),recurring:false,notes:''});setPage('Decision Lab')}
const filtered=data.transactions.filter(x=>(filter==='All'||x.type===filter.toLowerCase())&&((x.name+' '+x.category).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>sort==='new'?(b.date||'').localeCompare(a.date||''):sort==='old'?(a.date||'').localeCompare(b.date||''):sort==='high'?b.amount-a.amount:a.amount-b.amount);
function PageHead({eyebrow,title,sub,action}){return html`<div className="page-head"><div><div className="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action||null}</div>`}
function Stat({label,value,foot,ico,tone}){return html`<div className="stat"><div className="stat-top"><span>${label}</span><span className="stat-icon">${icon(ico)}</span></div><div className="stat-value ${tone||''}">${value}</div><div className="stat-foot">${foot}</div></div>`}
function PanelHead({title,sub,action}){return html`<div className="panel-head"><div><div className="panel-title">${title}</div><div className="panel-sub">${sub}</div></div>${action||null}</div>`}
function txIcon(x){return icon(iconMap[x.category]||'circle-dollar-sign')}
function TxRow({x}){return html`<div className="transaction"><div className="tx-icon">${txIcon(x)}</div><div><div className="tx-name">${x.name}</div><div className="tx-meta">${x.category} · ${x.date||'No date'}</div></div><div className="tx-amount ${x.type==='income'?'positive':''}">${x.type==='income'?'+':'−'}${money(x.amount)}<small>${x.type==='income'?'Income':x.type==='expense'?'Expense':'Note'}</small></div></div>`}
function SpendingChart(){const days=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-(6-i));const key=date.toISOString().slice(0,10);return {label:date.toLocaleDateString('en-IN',{weekday:'short'}),amount:data.transactions.filter(x=>x.type==='expense'&&x.date===key).reduce((s,x)=>s+x.amount,0)}});const max=Math.max(100,...days.map(x=>x.amount));const pts=days.map((x,i)=>({x:12+i* (276/6),y:142-(x.amount/max)*108}));const path=pts.map((p,i)=>(i?'L':'M')+p.x+' '+p.y).join(' ');const area=path+' L288 145 L12 145 Z';return html`<div className="chart-wrap"><svg viewBox="0 0 300 175" role="img" aria-label="Daily expenses over the last seven days"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#b8df83" stop-opacity=".4"/><stop offset="100%" stop-color="#b8df83" stop-opacity="0"/></linearGradient></defs>${[35,72,109,145].map(y=>html`<line x1="8" y1=${y} x2="292" y2=${y} stroke="#edf0e9" stroke-dasharray="3 4"/>`)}<path d=${area} fill="url(#area)"/><path d=${path} fill="none" stroke="#719c4c" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>${pts.map((p,i)=>html`<circle cx=${p.x} cy=${p.y} r="3.5" fill="#fff" stroke="#719c4c" stroke-width="2"/><text x=${p.x} y="165" text-anchor="middle" fill="#8a9285" font-size="9">${days[i].label}</text>`)}</svg></div><div className="chart-legend"><span><i className="legend-dot"></i>Daily spend</span><span className="muted">Last 7 days · real entries only</span></div>`}
function CategoryBreakdown(){const items=categories.map(c=>({name:c,amount:data.transactions.filter(x=>x.type==='expense'&&x.category===c).reduce((s,x)=>s+x.amount,0)})).filter(x=>x.amount>0).sort((a,b)=>b.amount-a.amount).slice(0,5),total=metrics.spent;return items.length?html`<div className="category-list">${items.map(c=>html`<div className="cat-row"><div className="cat-icon">${icon(iconMap[c.name]||'circle-dot')}</div><div className="cat-meta"><strong>${c.name}</strong><div className="bar"><span style=${{width:Math.min(100,c.amount/Math.max(1,items[0].amount)*100)+'%'}}></span></div></div><div className="cat-amount">${money(c.amount)}<div className="cat-meta muted" className="cat-meta muted tiny-gap">${Math.round(c.amount/Math.max(1,total)*100)}%</div></div></div>`)}</div>`:html`<div className="empty">Your categories will take shape as you add real transactions.</div>`}
function coachInsight(){if(metrics.balance<0)return {title:'You’re already below zero.',body:'Your recorded expenses exceed your starting funds and income. Pause discretionary spending and review every upcoming commitment.',action:'Review transactions'};if(metrics.spendable<0)return {title:'Commitments exceed your free cash.',body:'Your current balance cannot cover unpaid bills and protected savings together. Revisit optional bills or savings allocations before new spending.',action:'Review bills'};if(metrics.remaining>0&&metrics.dailyActual>metrics.plannedDaily*1.2)return {title:'Your spending pace is running hot.',body:'Your average daily spend is '+money(metrics.dailyActual)+', versus a starting pace of '+money(metrics.plannedDaily)+'. Cutting discretionary spend can preserve more runway.',action:'Open Decision Lab'};if(metrics.unpaid.some(b=>b.essential)&&metrics.balance<metrics.essential)return {title:'Protect essential payments first.',body:'Your current balance is below the amount marked as essential and unpaid. Delay optional purchases until those obligations are covered.',action:'Review bills'};return {title:'Keep your next move intentional.',body:'You have '+money(metrics.spendable)+' after unpaid bills and protected goal allocations. Simulate a purchase first to see its impact on your month-end outlook.',action:'Simulate a decision'}}
function overview(){const insight=coachInsight();return html`<${PageHead} eyebrow="YOUR MONEY, WITHOUT THE DRAMA" title="Make it to month-end." sub="A clearer view of what you have, what you owe, and what comes next." action=${html`<button className="btn" onClick=${startDecision}>${icon('flask-conical')} Simulate a decision</button>`}/><section className="hero"><div><div className="hero-label"><span className="live-dot"></span> ${t.remaining}</div><div className="balance"><span className="currency">₹</span>${Math.abs(metrics.balance).toLocaleString('en-IN',{maximumFractionDigits:0})}${metrics.balance<0?' in deficit':''}</div><div className="hero-sub">of ${money(data.budget)} starting budget · ${money(metrics.spent)} spent so far</div><div className="hero-actions"><button className="btn btn-lime" onClick=${()=>{setEditing(null);setModal('transaction')}}>${icon('plus')} Add transaction</button><button className="btn" style=${{background:'#ffffff12',border:'1px solid #ffffff25'}} onClick=${()=>setPage('Budget Planner')}>Plan my budget ${icon('arrow-up-right')}</button></div></div><div className="hero-right"><div className="runway-head"><span>30-day budget used</span><strong>${Math.min(999,Math.round(metrics.spent/Math.max(1,data.budget)*100))}%</strong></div><div className="runway"><span style=${{width:Math.min(100,metrics.spent/Math.max(1,data.budget)*100)+'%',background:metrics.spent>data.budget?'#e66e5f':'var(--mint)'}}></span></div><div className="runway-days"><span>Day ${Math.min(data.days,metrics.elapsed+1)} of ${data.days}</span><span>${metrics.remaining} days left</span></div><div className="hero-mini"><div><label>Safe to spend today</label><strong>${money(metrics.daily)}</strong><small>After bills & savings</small></div><div><label>Month-end projection</label><strong className="${metrics.projected<0?'negative':''}">${money(metrics.projected)}</strong><small>At your current pace</small></div></div></div></section><div className="grid stats"><${Stat} label="Income received" value=${money(metrics.income)} foot="Added on top of your budget" ico="trending-up" tone="positive"/><${Stat} label="Total spent" value=${money(metrics.spent)} foot="Recorded expenses only" ico="arrow-up-right"/><${Stat} label="Unpaid commitments" value=${money(metrics.committed)} foot=${metrics.unpaid.length+' bill(s) not yet paid'} ico="calendar-clock" tone=${metrics.committed?'':''}/><${Stat} label="Financial health" value=${metrics.score+'/100'} foot=${metrics.risk+' · heuristic estimate'} ico="heart-pulse" tone=${metrics.risk==='Healthy'?'positive':metrics.risk==='Caution'?'':'negative'}/></div><div className="grid content-grid"><section className="panel"><${PanelHead} title=${t.spending} sub="Seven-day view from your recorded expenses" action=${html`<button className="text-link" onClick=${()=>setPage('Transactions')}>All activity ↗</button>`}/><${SpendingChart}/></section><section className="panel"><${PanelHead} title=${t.categories} sub="Actual spending by category"/><${CategoryBreakdown}/></section></div><div className="grid bottom-grid"><section className="panel"><${PanelHead} title=${t.recent} sub="Your latest money movements" action=${html`<button className="text-link" onClick=${()=>setPage('Transactions')}>View all ↗</button>`}/>${data.transactions.length?html`<div className="transaction-list">${data.transactions.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,5).map(x=>html`<${TxRow} x=${x}/>`)}</div>`:html`<div className="empty">No transactions yet. Add your first expense or income to make this dashboard yours.</div>`}</section><section className="coach"><div className="coach-mark">${icon('sparkles')}</div><div className="coach-label">BARELY. MONEY NOTE</div><h3>${insight.title}</h3><p>${insight.body}</p><button className="btn" onClick=${()=>{if(insight.action==='Review transactions')setPage('Transactions');else if(insight.action==='Review bills')setPage('Bills & Subscriptions');else startDecision()}}>${insight.action} ${icon('arrow-up-right')}</button></section></div>`}
function transactionPage(){return html`<${PageHead} eyebrow="EVERY RUPEE, ACCOUNTED FOR" title="Transactions" sub="Your money in and out. No mystery maths." action=${html`<button className="btn" onClick=${()=>{setEditing(null);setModal('transaction')}}>${icon('plus')} Add transaction</button>`}/><div className="panel"><div className="table-tools"><input className="field" placeholder="Search description or category…" value=${query} onChange=${e=>setQuery(e.target.value)}/><select className="field" value=${filter} onChange=${e=>setFilter(e.target.value)}><option>All</option><option>Expense</option><option>Income</option></select><select className="field" value=${sort} onChange=${e=>setSort(e.target.value)}><option value="new">Newest first</option><option value="old">Oldest first</option><option value="high">Amount: high to low</option><option value="low">Amount: low to high</option></select><button className="btn btn-outline" onClick=${exportCSV}>${icon('download')} Export CSV</button></div><div className="table-wrap"><table className="table"><thead><tr><th>Description</th><th>Date</th><th>Category</th><th>Type</th><th>Amount</th><th>Actions</th></tr></thead><tbody>${filtered.length?filtered.map(x=>html`<tr><td><strong>${x.name}</strong></td><td>${x.date||'—'}</td><td>${x.category}</td><td><span className="tag ${x.type==='expense'?'warn':''}">${x.type}</span></td><td className="${x.type==='income'?'positive':''}">${money(x.amount)}</td><td><div className="actions"><button className="icon-btn" aria-label="Edit transaction" onClick=${()=>{setEditing(x);setModal('transaction')}}>${icon('pencil')}</button><button className="icon-btn" aria-label="Delete transaction" onClick=${()=>deleteTx(x.id)}>${icon('trash-2')}</button></div></td></tr>`):html`<tr><td colspan="6"><div className="empty">No matching transactions. Add an entry or adjust your filters.</div></td></tr>`}</tbody></table></div><div className="panel-sub" className="panel-sub export-foot">${filtered.length} entries · totals recalculate immediately when edited or deleted</div></div><div className="panel section-space"><${PanelHead} title="Quick Add" sub="Type a sentence; check the interpretation before saving."/><div className="table-tools"><input className="field" placeholder='Try “Spent 250 on lunch” or “Received 2000 from work”' value=${quick} onChange=${e=>{setQuick(e.target.value);setParsed(null)}} onKeyDown=${e=>{if(e.key==='Enter')quickParse()}}/><button className="btn" onClick=${quickParse}>${icon('wand-sparkles')} Parse command</button></div>${parsed?html`<div className="notice">Review before saving — this parser uses simple rules, not an AI model.</div><div className="form-grid"><div className="form-field"><label>Description</label><input className="field" value=${parsed.name} onChange=${e=>setParsed({...parsed,name:e.target.value})}/></div><div className="form-field"><label>Amount (₹)</label><input className="field" type="number" value=${parsed.amount} onChange=${e=>setParsed({...parsed,amount:Number(e.target.value)})}/></div><div className="form-field"><label>Type</label><select className="field" value=${parsed.type} onChange=${e=>setParsed({...parsed,type:e.target.value,category:e.target.value==='income'?'Other income':'Other'})}><option value="expense">Expense</option><option value="income">Income</option></select></div><div className="form-field"><label>Category</label><select className="field" value=${parsed.category} onChange=${e=>setParsed({...parsed,category:e.target.value})}>${(parsed.type==='income'?incomeCats:categories).map(c=>html`<option>${c}</option>`)}</select></div></div><div className="form-actions"><button className="btn btn-outline" onClick=${()=>setParsed(null)}>Cancel</button><button className="btn" onClick=${commitParsed}>Confirm & save</button></div>`:null}</div>`}
function decisionPage(){const amt=Math.max(0,Number(decision.amount)||0),sign=decision.type==='income'?1:decision.type==='expense'?-1:0,afterBalance=metrics.balance+sign*amt,afterSpendable=metrics.spendable+sign*amt,afterProjection=metrics.projected+sign*amt,afterDaily=metrics.remaining?Math.max(0,afterSpendable/metrics.remaining):Math.max(0,afterSpendable),afterRisk=afterBalance<0||afterSpendable<0||afterProjection<0?'High risk':afterDaily<metrics.plannedDaily*.35?'Caution':'Healthy';return html`<${PageHead} eyebrow="THINK IT THROUGH BEFORE YOU SPEND" title="Decision Lab" sub="Try a money move. See the trade-off. Keep your real numbers untouched until you apply it."/><div className="notice">Simulation only: changing these fields does not change your budget. “Apply decision” saves a transaction only after you confirm.</div><div className="grid content-grid"><section className="panel"><${PanelHead} title="Build a scenario" sub="Change any input to update the preview instantly."/><div className="form-grid"><div className="form-field full"><label>What are you considering?</label><select className="field" value=${decision.type} onChange=${e=>setDecision({...decision,type:e.target.value})}><option value="expense">Spend money</option><option value="income">Receive income</option><option value="adjustment">Cancel / avoid a cost (no cash entry)</option></select></div><div className="form-field"><label>Amount (₹)</label><input className="field" type="number" min="0" value=${decision.amount} onChange=${e=>setDecision({...decision,amount:e.target.value})}/></div><div className="form-field"><label>Category</label><select className="field" value=${decision.category} onChange=${e=>setDecision({...decision,category:e.target.value})}>${categories.map(c=>html`<option>${c}</option>`)}</select></div><div className="form-field full"><label>Description</label><input className="field" value=${decision.name} onChange=${e=>setDecision({...decision,name:e.target.value})}/></div><div className="form-field"><label>Date</label><input className="field" type="date" value=${decision.date} onChange=${e=>setDecision({...decision,date:e.target.value})}/></div><div className="form-field"><label>Repeat?</label><select className="field" value=${decision.recurring?'yes':'no'} onChange=${e=>setDecision({...decision,recurring:e.target.value==='yes'})}><option value="no">One-time</option><option value="yes">Recurring monthly</option></select></div><div className="form-field full"><label>Notes (optional)</label><input className="field" value=${decision.notes} onChange=${e=>setDecision({...decision,notes:e.target.value})} placeholder="Anything you want to remember"/></div></div><div className="form-actions"><button className="btn btn-outline" onClick=${()=>setDecision({type:'expense',amount:'800',category:'Entertainment',name:'Movie night',date:today(),recurring:false,notes:''})}>Reset</button><button className="btn" onClick=${applyDecision}>Apply decision ${icon('arrow-right')}</button></div></section><section className="panel"><${PanelHead} title="Before vs after" sub="Same financial calculation rules as your overview."/><div className="decision-grid"><div className="decision-box"><small>BEFORE · AVAILABLE</small><strong>${money(metrics.balance)}</strong><span>Current recorded cash</span></div><div className="decision-box after"><small>AFTER · AVAILABLE</small><strong>${money(afterBalance)}</strong><span>${sign===1?'+':sign===-1?'−':'±'}${money(amt)} change</span></div><div className="decision-box"><small>BEFORE · DAILY SAFE</small><strong>${money(metrics.daily)}</strong><span>After unpaid bills & goals</span></div><div className="decision-box after"><small>AFTER · DAILY SAFE</small><strong>${money(afterDaily)}</strong><span>New daily allowance</span></div><div className="decision-box"><small>BEFORE · MONTH END</small><strong>${money(metrics.projected)}</strong><span>Current pace estimate</span></div><div className="decision-box after"><small>AFTER · MONTH END</small><strong>${money(afterProjection)}</strong><span>Same spending pace assumption</span></div></div><div className="risk-line"><span>Current risk</span><b>${metrics.risk}</b></div><div className="risk-line"><span>After this decision</span><b className="${afterRisk==='Healthy'?'positive':afterRisk==='Caution'?'':'negative'}">${afterRisk}</b></div><div className="decision-note">${afterSpendable<0?'This move leaves less than zero after unpaid bills and protected savings. Do not treat it as sustainable.':afterProjection<0?'At your current pace, this move could leave you short by month-end. Consider delaying it or reducing the amount.':afterDaily<metrics.plannedDaily*.5?'Your safe daily allowance drops well below half your original daily budget. Consider a lower-cost alternative.':decision.type==='income'?'This additional income improves your cash runway if it is actually received.':decision.type==='adjustment'?'Cancelling an expense does not create cash today; only future avoided costs should change a forecast.': 'Check essential obligations first. The preview is a scenario, not a guarantee of future spending.'}</div></section></div><section className="panel section-space"><${PanelHead} title="Try a different move" sub="Fast starting points — choose one, then adjust the details."/><div className="grid stats" className="grid stats compact-stats">${[{name:'Headphones',amount:2600,type:'expense',category:'Shopping'},{name:'Extra shift',amount:2000,type:'income',category:'Part-time work'},{name:'Unexpected bill',amount:1500,type:'expense',category:'Bills'},{name:'Small treat',amount:300,type:'expense',category:'Entertainment'}].map(x=>html`<button className="stat" className="stat scenario-pick" onClick=${()=>setDecision({...decision,...x,date:today(),recurring:false,notes:''})}><div className="stat-top">${x.type==='income'?'INCOME SCENARIO':'SPENDING SCENARIO'}</div><div className="stat-value scenario-name">${x.name}</div><div className="stat-foot">${money(x.amount)} · tap to test</div></button>`)}</div></section>`}
function budgetPage(){const spentPct=Math.min(100,metrics.spent/Math.max(1,data.budget)*100);return html`<${PageHead} eyebrow="GIVE EVERY RUPEE A JOB" title="Budget planner" sub="Tune your starting budget and timeline. Your transactions remain intact."/><div className="grid content-grid"><section className="panel"><${PanelHead} title="Your month" sub="Editable planning assumptions"/><div className="form-field"><label>Starting budget (₹)</label><input className="field" type="number" min="0" value=${data.budget} onChange=${e=>update({budget:Math.max(0,Number(e.target.value)||0)})}/></div><div className="form-field section-space"><label>Planning duration (days)</label><input className="field" type="number" min="1" max="365" value=${data.days} onChange=${e=>update({days:Math.min(365,Math.max(1,Number(e.target.value)||1))})}/></div><div className="form-field section-space"><label>Planning start date</label><input className="field" type="date" value=${data.startDate} onChange=${e=>update({startDate:e.target.value||today()})}/></div><div className="form-actions"><button className="btn btn-outline" onClick=${()=>update({budget:10000,days:30,startDate:today()})}>Restore challenge assumptions</button></div></section><section className="panel"><${PanelHead} title="Budget at a glance" sub="Calculated from your current records"/><div className="budget-number">${money(data.budget)}</div><div className="panel-sub">Initial budget</div><div className="section-space"><div className="runway-head muted-head"><span>Spent so far</span><strong className="ink">${money(metrics.spent)} / ${money(data.budget)}</strong></div><div className="runway light-runway"><span style=${{width:spentPct+'%',background:spentPct>100?'var(--red)':'#8bbd54'}}></span></div></div><div className="risk-line section-space"><span>Income received</span><b className="positive">${money(metrics.income)}</b></div><div className="risk-line"><span>Available cash</span><b>${money(metrics.balance)}</b></div><div className="risk-line"><span>Unpaid bills reserved</span><b>${money(metrics.committed)}</b></div><div className="risk-line"><span>Protected savings</span><b>${money(metrics.savings)}</b></div><div className="risk-line"><span>Safe daily amount</span><b>${money(metrics.daily)}</b></div><div className="risk-line"><span>Month-end estimate</span><b className="${metrics.projected<0?'negative':''}">${money(metrics.projected)}</b></div></section></div><div className="panel section-space"><${PanelHead} title="Category plan vs actual" sub="Actual entries grouped by category; no fictional planned values are shown."/><div className="table-wrap"><table className="table"><thead><tr><th>Category</th><th>Actual spending</th><th>Share of budget</th><th>Budget used</th></tr></thead><tbody>${categories.map(c=>{const n=data.transactions.filter(x=>x.type==='expense'&&x.category===c).reduce((s,x)=>s+x.amount,0);return html`<tr><td>${c}</td><td>${money(n)}</td><td>${Math.round(n/Math.max(1,data.budget)*100)}%</td><td className="min-width-cell"><div className="bar"><span style=${{width:Math.min(100,n/Math.max(1,data.budget)*100)+'%'}}></span></div></td></tr>`})}</tbody></table></div></div>`}
function billsPage(){function saveBill(b){if(!b.name||!Number.isFinite(b.amount)||b.amount<=0){notify('Enter a bill name and amount above ₹0.',true);return}update(d=>({...d,bills:editing?d.bills.map(x=>x.id===editing.id?{...b,id:editing.id}:x):[{...b,id:uid()},...d.bills]}));setModal(null);setEditing(null);notify('Bill saved')}return html`<${PageHead} eyebrow="NO SURPRISE DUE DATES" title="Bills & subscriptions" sub="Track commitments so your spendable balance stays honest." action=${html`<button className="btn" onClick=${()=>addModal('bill')}>${icon('plus')} Add bill</button>`}/><div className="grid stats"><${Stat} label="Unpaid total" value=${money(metrics.committed)} foot="Reserved from spendable cash" ico="calendar-clock"/><${Stat} label="Bills unpaid" value=${metrics.unpaid.length} foot="Not marked as paid" ico="receipt"/><${Stat} label="Essential unpaid" value=${money(metrics.essential)} foot="Bills you marked essential" ico="shield-check"/><${Stat} label="Available after bills" value=${money(metrics.balance-metrics.committed)} foot="Before savings allocations" ico="wallet"/></div><section className="panel"><${PanelHead} title="Your commitments" sub="Mark paid only after money actually leaves your balance."/>${data.bills.length?html`<div className="table-wrap"><table className="table"><thead><tr><th>Bill</th><th>Due date</th><th>Type</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${data.bills.map(b=>html`<tr><td><strong>${b.name}</strong></td><td>${b.due||'—'}</td><td>${b.essential?'Essential':'Optional'} ${b.recurring?'· Monthly':''}</td><td>${money(b.amount)}</td><td><span className="tag ${b.paid?'':'warn'}">${b.paid?'Paid':'Unpaid'}</span></td><td><div className="actions"><button className="icon-btn" title="${b.paid?'Mark unpaid':'Mark paid'}" onClick=${()=>{update(d=>({...d,bills:d.bills.map(x=>x.id===b.id?{...x,paid:!x.paid}:x),transactions:!b.paid?[{id:uid(),name:b.name,amount:b.amount,type:'expense',category:b.category||'Bills',date:today(),notes:'Bill marked paid'},...d.transactions]:d.transactions}));notify(b.paid?'Bill marked unpaid':'Bill paid and expense recorded')}}>${icon(b.paid?'rotate-ccw':'check')}</button><button className="icon-btn" aria-label="Edit bill" onClick=${()=>{setEditing(b);setModal('bill')}}>${icon('pencil')}</button><button className="icon-btn" aria-label="Delete bill" onClick=${()=>{if(confirm('Delete this bill?'))update(d=>({...d,bills:d.bills.filter(x=>x.id!==b.id)}))}}>${icon('trash-2')}</button></div></td></tr>`)}</tbody></table></div>`:html`<div className="empty">No bills added yet. Add rent, mobile recharge, transport or subscriptions to reserve their cost in your daily allowance.</div>`}</section><div className="notice section-space">Paid bills create an expense transaction once. Unpaid bills reduce spendable funds as reservations, not current cash, so the same bill is not deducted twice.</div>`}
function goalsPage(){function saveGoal(g){if(!g.name||g.target<=0){notify('Enter a goal name and target above ₹0.',true);return}update(d=>({...d,goals:editing?d.goals.map(x=>x.id===editing.id?{...g,id:editing.id}:x):[{...g,id:uid()},...d.goals]}));setModal(null);setEditing(null);notify('Savings goal saved')}return html`<${PageHead} eyebrow="SAVE WITHOUT FOOLING YOURSELF" title="Savings goals" sub="Track allocations separately from spending. A goal should fit the money you actually have." action=${html`<button className="btn" onClick=${()=>addModal('goal')}>${icon('plus')} Create a goal</button>`}/><div className="grid content-grid"><section className="panel"><${PanelHead} title="Your goals" sub="Saved amounts are protected from spendable cash."/>${data.goals.length?data.goals.map(g=>html`<div className="goal"><div className="goal-head"><strong>${g.name}</strong><span>${money(g.saved)} / ${money(g.target)}</span></div><div className="bar"><span style=${{width:Math.min(100,g.saved/Math.max(1,g.target)*100)+'%'}}></span></div><div className="panel-sub">${Math.round(g.saved/Math.max(1,g.target)*100)}% complete · Target ${g.due||'not set'}</div><div className="actions section-space"><button className="btn btn-outline" onClick=${()=>{setEditing(g);setModal('contribute')}}>Add contribution</button><button className="btn btn-outline" onClick=${()=>{setEditing(g);setModal('goal')}}>Edit goal</button><button className="icon-btn" aria-label="Delete goal" onClick=${()=>{if(confirm('Delete this goal?'))update(d=>({...d,goals:d.goals.filter(x=>x.id!==g.id)}))}}>${icon('trash-2')}</button></div></div>`):html`<div className="empty">Create a goal to give your savings a purpose.</div>`}</section><section className="panel"><${PanelHead} title="Can you afford it?" sub="Simple feasibility check using your current free cash."/><div className="budget-number">${money(metrics.spendable)}</div><div className="panel-sub">Spendable after unpaid bills and existing savings</div><div className="risk-line section-space"><span>Total goal allocations</span><b>${money(metrics.savings)}</b></div><div className="risk-line"><span>Goal progress (average)</span><b>${metrics.goalProgress}%</b></div><div className="decision-note">${metrics.spendable<0?'Your allocations and bills exceed current cash. Reduce or withdraw a goal allocation before adding discretionary expenses.':'Savings are allocations, not consumption. Contributions reduce spendable funds but do not count as expenses in spending charts.'}</div></section></div>`}
function healthPage(){return html`<${PageHead} eyebrow="A CLEAR-EYED CHECK-IN" title="Financial health" sub="A transparent rule-based estimate, not a credit score or professional financial advice."/><div className="grid content-grid"><section className="panel"><${PanelHead} title="Your current snapshot" sub="Derived from your actual entries and commitments."/><div className="health-overview"><div className="health-ring" style=${{'--score':metrics.score*3.6+'deg'}}><strong>${metrics.score}</strong></div><div><div className="subhead">${metrics.risk}</div><p className="muted health-explainer">This heuristic weighs spending pace, spendable cash and essential bill coverage. It is a practical indicator, not a validated financial assessment.</p></div></div><div className="risk-line section-space"><span>Available cash</span><b>${money(metrics.balance)}</b></div><div className="risk-line"><span>Spendable after reservations</span><b className="${metrics.spendable<0?'negative':''}">${money(metrics.spendable)}</b></div><div className="risk-line"><span>Essential bill coverage</span><b>${metrics.balance>=metrics.essential?'Covered':'Short by '+money(metrics.essential-metrics.balance)}</b></div><div className="risk-line"><span>Average daily spending</span><b>${money(metrics.dailyActual)}</b></div><div className="risk-line"><span>Starting daily budget pace</span><b>${money(metrics.plannedDaily)}</b></div><div className="risk-line"><span>Estimated cash runway</span><b>${metrics.dailyActual>0?Math.floor(Math.max(0,metrics.spendable)/metrics.dailyActual)+' days':'Not enough spending history'}</b></div></section><section className="panel"><${PanelHead} title="What the status means" sub="Rules are explicit and intentionally simple."/><div className="risk-line"><span><i className="legend-dot"></i> Healthy</span><b>Cash covers current obligations and pace is sustainable.</b></div><div className="risk-line"><span><i className="legend-dot amber-dot"></i> Caution</span><b>Spendable funds are thin or spending pace is elevated.</b></div><div className="risk-line"><span><i className="legend-dot red-dot"></i> High risk</span><b>Negative cash, negative spendable balance or projected deficit.</b></div><div className="notice section-space">The score is a heuristic that updates with your records. It is not scientifically validated, and it cannot predict emergencies or future income with certainty.</div></section></div>`}
function coachPage(){const insight=coachInsight();const items=[{title:insight.title,body:insight.body,impact:'Current available cash: '+money(metrics.balance)+'. Spendable after reservations: '+money(metrics.spendable)+'.',action:insight.action},{title:'Know your real daily ceiling.',body:'Your current safe allowance is '+money(metrics.daily)+' for each of '+metrics.remaining+' remaining planning days. This is after unpaid bills and protected savings.',impact:'Original budget pace: '+money(metrics.plannedDaily)+' per day.',action:'Open Budget Planner'},{title:'Your forecast has assumptions.',body:'Month-end projection uses your recent average expense pace, remaining days and unpaid commitments. Sparse history makes it less reliable.',impact:'Current projection: '+money(metrics.projected)+'.',action:'Open Transactions'}];return html`<${PageHead} eyebrow="PRACTICAL, PERSONAL, NO GUILT" title="Money coach" sub="Specific next steps based on your records — no generic motivational quotes."/><div className="panel"><${PanelHead} title="Your next best moves" sub="Recommendations recalculate when your money data changes."/>${items.map((x,i)=>html`<div className="coach-card"><strong>${i+1<10?'0'+(i+1):i+1} / ${x.title}</strong><p>${x.body}</p><p><b>${x.impact}</b></p><button className="btn btn-outline" onClick=${()=>setPage(x.action==='Open Budget Planner'?'Budget Planner':x.action==='Open Transactions'?'Transactions':x.action==='Review bills'?'Bills & Subscriptions':'Decision Lab')}>${x.action} ${icon('arrow-up-right')}</button></div>`)}</div><div className="notice section-space">barely. offers educational budgeting guidance based on data you enter. It does not access your bank account or know about expenses you have not recorded.</div>`}
function settingsPage(){return html`<${PageHead} eyebrow="MAKE IT YOURS" title="Settings" sub="Control the planning assumptions and your locally saved data."/><div className="panel"><div className="settings-row"><div><strong>Interface language</strong><p>Change supported navigation and key dashboard labels.</p></div><select className="field" value=${data.lang} onChange=${e=>update({lang:e.target.value})}>${['English','Tamil','Hindi','Telugu','Malayalam','Bengali'].map(x=>html`<option>${x}</option>`)}</select></div><div className="settings-row"><div><strong>Starting monthly budget</strong><p>Official challenge default is ₹10,000.</p></div><strong>${money(data.budget)}</strong></div><div className="settings-row"><div><strong>Planning duration</strong><p>Days in the current plan.</p></div><strong>${data.days} days</strong></div><div className="settings-row"><div><strong>Data storage</strong><p>Saved in this browser on this device. Clearing browser storage removes it.</p></div><span className="tag">Local-first</span></div><div className="settings-row"><div><strong>Export transactions</strong><p>Download transaction history as a CSV file.</p></div><button className="btn btn-outline" onClick=${exportCSV}>${icon('download')} Export CSV</button></div><div className="settings-row"><div><strong>Reset demo scenario</strong><p>Remove local entries and restore the original empty ₹10,000 / 30-day setup.</p></div><button className="btn danger-btn" onClick=${reset}>Reset data</button></div></div><div className="notice section-space">Privacy note: this prototype stores financial entries in local browser storage only. It does not connect to a bank, sync to the cloud, or encrypt data at rest.</div>`}
function modalContent(){if(!modal)return null;const kind=modal;const isTx=kind==='transaction',isBill=kind==='bill',isGoal=kind==='goal',isContribution=kind==='contribute';const [unused]=[];let title=isTx?(editing?'Edit transaction':'Add transaction'):isBill?(editing?'Edit bill':'Add bill'):isGoal?(editing?'Edit savings goal':'Create savings goal'):isContribution?'Add a contribution':'';
const [form,setForm]=[null,null];return html`<${ModalForm} kind=${kind} editing=${editing} onClose=${()=>{setModal(null);setEditing(null)}} onSave=${(v)=>{if(isTx)transact(v);else if(isBill)saveBillModal(v);else if(isGoal)saveGoalModal(v);else contributionModal(v)}}/>`}
function saveBillModal(b){if(!b.name||b.amount<=0){notify('Enter a bill name and valid amount.',true);return}update(d=>({...d,bills:editing?d.bills.map(x=>x.id===editing.id?{...b,id:editing.id}:x):[{...b,id:uid()},...d.bills]}));setModal(null);setEditing(null);notify('Bill saved')}
function saveGoalModal(g){if(!g.name||g.target<=0){notify('Enter a goal name and valid target.',true);return}update(d=>({...d,goals:editing?d.goals.map(x=>x.id===editing.id?{...g,id:editing.id}:x):[{...g,id:uid()},...d.goals]}));setModal(null);setEditing(null);notify('Goal saved')}
function contributionModal(v){const amount=Number(v.amount);if(!Number.isFinite(amount)||amount<=0){notify('Enter a valid contribution amount.',true);return}const goal=editing;if(!goal)return;if(v.mode==='add'&&amount>metrics.spendable){notify('This contribution exceeds spendable funds after bills and existing savings.',true);return}update(d=>({...d,goals:d.goals.map(g=>g.id===goal.id?{...g,saved:Math.max(0,g.saved+(v.mode==='add'?amount:-amount))}:g)}));setModal(null);setEditing(null);notify(v.mode==='add'?'Contribution added':'Contribution withdrawn')}
function ModalForm({kind,editing,onClose,onSave}){const isTx=kind==='transaction',isBill=kind==='bill',isGoal=kind==='goal',isContribution=kind==='contribute';const initial=editing|| (isTx?{name:'',amount:'',type:'expense',category:'Food',date:today(),notes:''}:isBill?{name:'',amount:'',due:today(),category:'Bills',essential:true,recurring:false,paid:false}:isGoal?{name:'',target:'',saved:0,due:today()}:{amount:'',mode:'add'});const [v,setV]=useState({...initial});const set=(k,val)=>setV(old=>({...old,[k]:val}));const title=isTx?(editing?'Edit transaction':'Add transaction'):isBill?(editing?'Edit bill':'Add bill'):isGoal?(editing?'Edit savings goal':'Create savings goal'):'Goal contribution';function submit(){if(isTx){const amount=Number(v.amount);if(!v.name.trim()||!Number.isFinite(amount)||amount<=0){notify('Enter a description and amount above ₹0.',true);return}onSave({...v,amount,type:v.type,category:v.category||'Other',date:v.date||today()})}else if(isBill){const amount=Number(v.amount);if(!v.name.trim()||!Number.isFinite(amount)||amount<=0){notify('Enter a bill name and amount above ₹0.',true);return}onSave({...v,amount,category:v.category||'Bills',due:v.due||today(),essential:!!v.essential,recurring:!!v.recurring,paid:!!v.paid})}else if(isGoal){const target=Number(v.target),saved=Number(v.saved)||0;if(!v.name.trim()||!Number.isFinite(target)||target<=0||saved<0){notify('Enter a goal name and positive target.',true);return}if(!editing&&saved>metrics.spendable){notify('Starting savings cannot exceed current spendable funds.',true);return}onSave({...v,target,saved,due:v.due||today()})}else onSave(v)}return html`<div className="modal-backdrop" onClick=${e=>{if(e.target===e.currentTarget)onClose()}}><section className="modal" role="dialog" aria-modal="true" aria-label=${title}><div className="modal-head"><div><div className="eyebrow">BARELY. · YOUR MONEY</div><h2>${title}</h2><p>Changes update your calculations immediately after saving.</p></div><button className="close" aria-label="Close dialog" onClick=${onClose}>×</button></div><div className="form-grid">${isTx?html`<div className="form-field full"><label>Description</label><input autoFocus className="field" value=${v.name||''} onChange=${e=>set('name',e.target.value)} placeholder="e.g. Lunch, bus pass, freelance work"/></div><div className="form-field"><label>Amount (₹)</label><input className="field" type="number" min="1" value=${v.amount} onChange=${e=>set('amount',e.target.value)} /></div><div className="form-field"><label>Type</label><select className="field" value=${v.type||'expense'} onChange=${e=>set('type',e.target.value)}><option value="expense">Expense</option><option value="income">Income</option></select></div><div className="form-field"><label>Category</label><select className="field" value=${v.category||'Other'} onChange=${e=>set('category',e.target.value)}>${(v.type==='income'?incomeCats:categories).map(c=>html`<option>${c}</option>`)}</select></div><div className="form-field"><label>Date</label><input className="field" type="date" value=${v.date||today()} onChange=${e=>set('date',e.target.value)}/></div><div className="form-field full"><label>Notes (optional)</label><input className="field" value=${v.notes||''} onChange=${e=>set('notes',e.target.value)} placeholder="A note for future you"/></div>`:isBill?html`<div className="form-field full"><label>Bill or subscription name</label><input className="field" autoFocus value=${v.name||''} onChange=${e=>set('name',e.target.value)} placeholder="e.g. Mobile recharge"/></div><div className="form-field"><label>Amount (₹)</label><input className="field" type="number" min="1" value=${v.amount} onChange=${e=>set('amount',e.target.value)}/></div><div className="form-field"><label>Due date</label><input className="field" type="date" value=${v.due||today()} onChange=${e=>set('due',e.target.value)}/></div><div className="form-field"><label>Category</label><select className="field" value=${v.category||'Bills'} onChange=${e=>set('category',e.target.value)}>${categories.map(c=>html`<option>${c}</option>`)}</select></div><div className="form-field"><label>Importance</label><select className="field" value=${v.essential?'yes':'no'} onChange=${e=>set('essential',e.target.value==='yes')}><option value="yes">Essential</option><option value="no">Optional</option></select></div><div className="form-field full"><label>Recurrence</label><select className="field" value=${v.recurring?'yes':'no'} onChange=${e=>set('recurring',e.target.value==='yes')}><option value="no">One-time</option><option value="yes">Monthly recurring (tracking only)</option></select></div>`:isGoal?html`<div className="form-field full"><label>Goal name</label><input className="field" autoFocus value=${v.name||''} onChange=${e=>set('name',e.target.value)} placeholder="e.g. Emergency buffer"/></div><div className="form-field"><label>Target amount (₹)</label><input className="field" type="number" min="1" value=${v.target} onChange=${e=>set('target',e.target.value)}/></div><div className="form-field"><label>Already saved (₹)</label><input className="field" type="number" min="0" value=${v.saved||0} onChange=${e=>set('saved',e.target.value)}/></div><div className="form-field full"><label>Target date</label><input className="field" type="date" value=${v.due||today()} onChange=${e=>set('due',e.target.value)}/></div>`:html`<div className="form-field full"><label>Amount (₹)</label><input className="field" autoFocus type="number" min="1" value=${v.amount} onChange=${e=>set('amount',e.target.value)}/></div><div className="form-field full"><label>Action</label><select className="field" value=${v.mode||'add'} onChange=${e=>set('mode',e.target.value)}><option value="add">Add money to goal</option><option value="remove">Withdraw from goal allocation</option></select></div><div className="form-field full"><p>Goal: ${editing?editing.name:''}. Contributions are allocations, not consumption expenses.</p></div>`}</div><div className="form-actions"><button className="btn btn-outline" onClick=${onClose}>Cancel</button><button className="btn" onClick=${submit}>Save changes</button></div></section></div>`}
function renderPage(){switch(page){case'Overview':return overview();case'Transactions':return transactionPage();case'Decision Lab':return decisionPage();case'Budget Planner':return budgetPage();case'Bills & Subscriptions':return billsPage();case'Savings Goals':return goalsPage();case'Financial Health':return healthPage();case'Money Coach':return coachPage();case'Settings':return settingsPage();default:return overview()}}
const navButton=(item,mobile=false)=>html`<button className=${page===item[0]?'active':''} onClick=${()=>setPage(item[0])}>${icon(item[1])}<span>${t[item[0]]||item[0]}</span></button>`;
return html`<div className="app"><aside className="sidebar"><div className="brand">barely<span className="brand-dot">.</span><small>MAKE IT TO MONTH-END</small></div><div><div className="nav-label">YOUR MONEY</div><nav className="nav">${navItems.map(x=>navButton(x))}</nav></div><div className="sidebar-bottom"><div className="challenge"><strong>${metrics.risk==='Healthy'?'You’re holding steady.':metrics.risk==='Caution'?'A little caution goes far.':'Time to protect your runway.'}</strong><p>${money(metrics.spendable)} left after unpaid bills and savings. ${metrics.remaining} planning days to go.</p><div className="meter"><span style=${{width:Math.max(0,Math.min(100,metrics.balance/Math.max(1,data.budget)*100))+'%'}}></span></div></div></div></aside><main className="main"><header className="topbar"><div className="mobile-top">barely<span className="brand-dot">.</span></div><div className="crumb">Your finances <span className="crumb-separator">/</span> <b>${t[page]||page}</b></div><div className="top-actions"><select className="pill" aria-label="Interface language" value=${data.lang} onChange=${e=>update({lang:e.target.value})}>${['English','Tamil','Hindi','Telugu','Malayalam','Bengali'].map(x=>html`<option>${x}</option>`)}</select><button className="avatar" aria-label="Open settings" onClick=${()=>setPage('Settings')}>MM</button></div></header>${renderPage()}</main><nav className="mobile-nav" aria-label="Main navigation">${[['Overview','layout-dashboard'],['Transactions','arrow-left-right'],['Decision Lab','flask-conical'],['Budget Planner','sliders-horizontal'],['Settings','menu']].map(x=>navButton(x,true))}</nav>${modal?html`<${ModalForm} kind=${modal} editing=${editing} onClose=${()=>{setModal(null);setEditing(null)}} onSave=${v=>{if(modal==='transaction')transact(v);else if(modal==='bill')saveBillModal(v);else if(modal==='goal')saveGoalModal(v);else contributionModal(v)}}/>`:null}${toast?html`<div className="toast ${toast.error?'error':''}" role="status">${toast.message}</div>`:null}</div>`}
ReactDOM.createRoot(document.getElementById('root')).render(html`<${App}/>`);
})();